import type { ReactNode } from "react"

export function Tool({ name, status, children }: { name: string; status: string; children?: ReactNode }) {
  return (
    <section className="tool" aria-label={`${name} tool ${status}`}>
      <div className="tool-heading"><strong>{name}</strong><span>{status}</span></div>
      {children && <div className="tool-details">{children}</div>}
    </section>
  )
}

